--
-- Table structure for table `tickets`
--

DROP TABLE IF EXISTS `tickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tickets` (
  `id` binary(16) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `other_reason` varchar(1000) DEFAULT NULL,
  `report_reason` enum('HARASSMENT','INAPPROPRIATE_CONTENT','MISINFORMATION','OTHER','SPAM') NOT NULL,
  `state` enum('CLOSED','OPEN') NOT NULL,
  `story_conditions_snapshot` varchar(2000) DEFAULT NULL,
  `story_content_snapshot` text,
  `story_title_snapshot` varchar(255) DEFAULT NULL,
  `type` enum('STORY') NOT NULL,
  `reportee_id` binary(16) DEFAULT NULL,
  `reporter_id` binary(16) DEFAULT NULL,
  `story_id` binary(16) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK9qgsuap9sklssmoucw705kl5u` (`reportee_id`),
